use std::io::{self, Read, Write};

fn percentage_f64promote(value: f32, precision: i32) -> String {
    let p: usize = if precision < 0 { 6 } else { precision as usize };
    format!("{:.*}%", p, (value * 100.0f32) as f64)
}
fn percentage_f32direct(value: f32, precision: i32) -> String {
    let p: usize = if precision < 0 { 6 } else { precision as usize };
    format!("{:.*}%", p, value * 100.0f32)
}
fn percentage_f64mul(value: f32, precision: i32) -> String {
    let p: usize = if precision < 0 { 6 } else { precision as usize };
    format!("{:.*}%", p, (value as f64) * 100.0f64)
}
fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let out = io::stdout();
    let mut w = io::BufWriter::new(out.lock());
    let mut it = s.split_ascii_whitespace();
    while let (Some(a), Some(b)) = (it.next(), it.next()) {
        let bits = u32::from_str_radix(a, 16).unwrap();
        let prec: i32 = b.parse().unwrap();
        let f = f32::from_bits(bits);
        let r = match mode.as_str() {
            "direct" => percentage_f32direct(f, prec),
            "f64mul" => percentage_f64mul(f, prec),
            _ => percentage_f64promote(f, prec),
        };
        writeln!(w, "{}", r).unwrap();
    }
}
