// namespace indicators { struct Format { ... }; }  -> a unit struct with associated fns.
pub struct Format;

impl Format {
    /// C++: static std::string percentage(float value, int precision = 1);
    /// `value` is a FRACTION (0.25 -> "25.0%"). It is NOT clamped or validated.
    pub fn percentage(value: f32, precision: i32) -> String {
        // std::setprecision(<0) reaches glibc as "%.*f" with a negative `*`,
        // which the C standard says means "precision omitted" -> %f default of 6.
        let p: usize = if precision < 0 { 6 } else { precision as usize };

        // CRITICAL: the x100 is a SINGLE-PRECISION multiply (mulss 100.0f), and it
        // may overflow to inf for huge inputs. Do NOT write `(value as f64) * 100.0`.
        let scaled: f32 = value * 100.0f32;

        // C++ streams promote float->double via operator<<(double) (cvtss2sd).
        // That promotion is value-exact, so `scaled as f64` and `scaled` format
        // identically; the `as f64` is documentation of the C++ promotion, not a
        // behavioural requirement. Either line below is correct:
        format!("{:.*}%", p, scaled as f64)
        // equivalently: format!("{:.*}%", p, scaled)
        // literal-precision form when precision is a constant: format!("{:.1}%", scaled)
    }

    /// The C++ default argument. Rust has no default args; expose either a second
    /// fn like this, or `percentage(v, precision: impl Into<Option<i32>>)`.
    #[inline]
    pub fn percentage_default(value: f32) -> String { Self::percentage(value, 1) }

    /// C++: static std::string progress(int current, int total);
    /// int == i32. No percentage, no padding, no separators, no division.
    pub fn progress(current: i32, total: i32) -> String {
        format!("{}/{}", current, total)
    }
}

